def canonical_json_sha256(value: Any) -> str:
    """Return the canonical JSON digest of *value*."""
    payload = json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def _frozen_task_contract() -> dict[str, Any]:
    """Return the task contract with its machine-local locators removed.

    A clone-specific receipt number, a prepared-file digest, or a filename
    inside one clone's media directory identifies one machine rather than the
    task, so the frozen contract states only the asset identities it does
    depend on.
    """

    contract = copy.deepcopy(TASK_SPEC)
    for key in (
        "manifest_sha256",
        "dataset_manifest_sha256",
        "golden_map_filename",
        "golden_map_sha256",
    ):
        contract["asset_binding"].pop(key, None)
    for session in contract["sessions"]:
        session["source_identity"].pop("media_relative_path", None)
    return contract


